import { MatchFormation, MatchWithSquad } from '../../../core/services/matches.service';
import { FormationColorGroup, FormationPreset } from './formation-presets';

// Brand palette (mirrors src/theme-palettes.scss / src/styles.scss) — the
// share card is built entirely out of the app's own tokens instead of
// inventing a separate "football graphic" palette, so it reads as a card
// generated BY Inter Mitente, not a generic lineup-maker export.
const NAVY_TOP = '#1a202a'; // theme-palettes neutral tone 12
const NAVY_BOTTOM = '#0e131d'; // theme-palettes neutral tone 6
const NAVY_PANEL = 'rgba(219, 227, 242, 0.05)'; // glass-card-ish lift, on neutral tone 90
const PANEL_BORDER = 'rgba(191, 199, 214, 0.18)'; // outline tone, mirrors --glass-card-border
const AMBER = '#ff9d00'; // --accent-amber
const VIOLET = '#ab75f8'; // --accent-violet
const ON_ACCENT_DARK = '#161c26'; // same dark-on-amber text used for CTA buttons app-wide

export const COLOR_GROUP_HEX: Record<FormationColorGroup, string> = {
  portero: AMBER,
  defensa: '#8ea8fd', // navy-palette tone 70 — a cool brand blue, not a generic bootstrap blue
  medio: '#3ecf8e',
  delantero: VIOLET,
};

const WIDTH = 1080;
const HEADER_HEIGHT = 260;
const LEGEND_HEIGHT = 90;
const BASE_PITCH_HEIGHT = 1180;
const PANEL_MARGIN = 48;
/** How many substitutes a slot shows by name before collapsing the rest
 * into a "+N más" line — keeps a single slot's text block bounded. */
const MAX_SUBS_SHOWN = 4;
/** Extra pitch-area pixels per substitute line beyond MAX_SUBS_SHOWN, added
 * to the canvas height so a slot with many subs still has room (the fixed
 * row y-spacing is otherwise calibrated for MAX_SUBS_SHOWN lines). */
const EXTRA_HEIGHT_PER_SUB = 26;

const DISPLAY_FONT = `'Bricolage Grotesque', Manrope, 'Helvetica Neue', sans-serif`;
const BODY_FONT = `Manrope, 'Helvetica Neue', sans-serif`;

let fontsReady: Promise<void> | null = null;

/** Loads the app's own self-hosted webfonts into the canvas context — the
 * share card is read standalone (in a WhatsApp chat), so it carries its own
 * copies rather than assuming the system font stack looks right. */
function ensureFontsLoaded(): Promise<void> {
  if (!fontsReady) {
    fontsReady = Promise.all([
      new FontFace('Bricolage Grotesque', "url('/fonts/bricolage-grotesque-800.woff2')", { weight: '800' }).load(),
      new FontFace('Manrope', "url('/fonts/manrope-variable.woff2')", { weight: '400 800' }).load(),
    ])
      .then(([display, body]) => {
        (document.fonts as FontFaceSet).add(display);
        (document.fonts as FontFaceSet).add(body);
      })
      .catch(() => {
        // Self-hosted font missing/blocked — canvas falls back to the
        // generic families already in DISPLAY_FONT/BODY_FONT's stacks.
      });
  }
  return fontsReady;
}

function loadImage(src: string): Promise<HTMLImageElement | null> {
  return new Promise((resolve) => {
    const img = new Image();
    img.onload = () => resolve(img);
    img.onerror = () => resolve(null);
    img.src = src;
  });
}

export function capSubNames(names: string[], max = MAX_SUBS_SHOWN): string[] {
  if (names.length <= max) return names;
  return [...names.slice(0, max), `+${names.length - max} más`];
}

/** Canvas height grows only when some slot has more possible subs than
 * MAX_SUBS_SHOWN fits by default — otherwise the fixed base height is used. */
export function computeCanvasHeight(formation: MatchFormation): number {
  const maxSubs = formation.slots.reduce((max, s) => Math.max(max, s.substitutes.length), 0);
  const extraSubs = Math.max(0, maxSubs - MAX_SUBS_SHOWN);
  const pitchHeight = BASE_PITCH_HEIGHT + extraSubs * EXTRA_HEIGHT_PER_SUB;
  return HEADER_HEIGHT + pitchHeight + LEGEND_HEIGHT;
}

/** The app's own two-glow "floodlight" treatment (see body background in
 * styles.scss) over a navy gradient — not a grass photo. The card is meant
 * to look like it was generated BY the app, not like a stock lineup-maker
 * export with the brand's colors painted over it. */
export function drawCardBackground(ctx: CanvasRenderingContext2D, width: number, height: number): void {
  const base = ctx.createLinearGradient(0, 0, width * 0.3, height);
  base.addColorStop(0, NAVY_TOP);
  base.addColorStop(1, NAVY_BOTTOM);
  ctx.fillStyle = base;
  ctx.fillRect(0, 0, width, height);

  const amberGlow = ctx.createRadialGradient(width * 0.9, 0, 0, width * 0.9, 0, width * 0.9);
  amberGlow.addColorStop(0, 'rgba(255, 157, 0, 0.16)');
  amberGlow.addColorStop(1, 'rgba(255, 157, 0, 0)');
  ctx.fillStyle = amberGlow;
  ctx.fillRect(0, 0, width, height);

  const violetGlow = ctx.createRadialGradient(width * -0.05, height * 0.35, 0, width * -0.05, height * 0.35, width);
  violetGlow.addColorStop(0, 'rgba(171, 117, 248, 0.12)');
  violetGlow.addColorStop(1, 'rgba(171, 117, 248, 0)');
  ctx.fillStyle = violetGlow;
  ctx.fillRect(0, 0, width, height);
}

function roundRectPath(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number) {
  ctx.beginPath();
  ctx.roundRect(x, y, w, h, r);
}

/** Shrinks a font size (down to `minPx`) until `text` fits `maxWidth`;
 * if it still doesn't fit at the floor size, truncates with an ellipsis.
 * Keeps a long player name from blowing out a slot's pill width or
 * colliding with its neighbors, instead of growing the pill unbounded. */
export function fitText(
  ctx: CanvasRenderingContext2D,
  text: string,
  buildFont: (px: number) => string,
  startPx: number,
  minPx: number,
  maxWidth: number
): { font: string; text: string; width: number } {
  let px = startPx;
  let font = buildFont(px);
  ctx.font = font;
  while (ctx.measureText(text).width > maxWidth && px > minPx) {
    px -= 1;
    font = buildFont(px);
    ctx.font = font;
  }
  let display = text;
  if (ctx.measureText(display).width > maxWidth) {
    while (ctx.measureText(display + '…').width > maxWidth && display.length > 1) {
      display = display.slice(0, -1);
    }
    display += '…';
  }
  return { font, text: display, width: ctx.measureText(display).width };
}

/** The glass-card panel the pitch diagram sits on, with thin schematic
 * pitch-line strokes — a tactical diagram, not a rendered photo, so it
 * stays in the app's own dark/navy register instead of a jarring green
 * rectangle dropped into an otherwise navy card. */
export function drawPitchPanel(ctx: CanvasRenderingContext2D, width: number, height: number): void {
  const top = HEADER_HEIGHT;
  const bottom = height - LEGEND_HEIGHT;
  const left = PANEL_MARGIN;
  const right = width - PANEL_MARGIN;

  ctx.fillStyle = NAVY_PANEL;
  roundRectPath(ctx, left, top, right - left, bottom - top, 28);
  ctx.fill();
  ctx.strokeStyle = PANEL_BORDER;
  ctx.lineWidth = 1.5;
  roundRectPath(ctx, left, top, right - left, bottom - top, 28);
  ctx.stroke();

  const lineMargin = 36;
  const lineTop = top + lineMargin;
  const lineBottom = bottom - lineMargin;
  const lineLeft = left + lineMargin;
  const lineRight = right - lineMargin;

  ctx.strokeStyle = 'rgba(255, 255, 255, 0.14)';
  ctx.lineWidth = 2;
  ctx.strokeRect(lineLeft, lineTop, lineRight - lineLeft, lineBottom - lineTop);

  ctx.beginPath();
  ctx.moveTo(lineLeft, (lineTop + lineBottom) / 2);
  ctx.lineTo(lineRight, (lineTop + lineBottom) / 2);
  ctx.stroke();

  ctx.beginPath();
  ctx.arc(width / 2, (lineTop + lineBottom) / 2, 90, 0, Math.PI * 2);
  ctx.stroke();

  const boxWidth = (lineRight - lineLeft) * 0.42;
  ctx.strokeRect(width / 2 - boxWidth / 2, lineBottom - 100, boxWidth, 100);
}

export interface SlotRenderData {
  x: number;
  y: number;
  colorGroup: FormationColorGroup;
  starterLabel: string;
  subLabels: string[]; // already capped via capSubNames
}

/** One slot's token: a filled rounded pill (same visual language as the
 * app's own status/rating pill badges) carrying the starter's name and
 * number, with substitutes listed smaller/italic underneath in a separate,
 * translucent pill rather than loose text floating on the pitch. */
export function drawSlot(
  ctx: CanvasRenderingContext2D,
  width: number,
  height: number,
  slot: SlotRenderData
): void {
  const top = HEADER_HEIGHT + 36;
  const pitchHeight = height - HEADER_HEIGHT - LEGEND_HEIGHT - 72;
  const cx = slot.x * width;
  const cy = top + slot.y * pitchHeight;
  const accent = COLOR_GROUP_HEX[slot.colorGroup];

  // Capped so a long name shrinks (and, as a last resort, truncates)
  // instead of growing wide enough to collide with a neighboring slot —
  // columns sit as close as ~280px apart in the 3-wide rows.
  const maxPillWidth = 260;
  const primaryPadX = 26;
  const primaryHeight = 52;
  const primaryBuildFont = (px: number) => `700 ${px}px ${DISPLAY_FONT}`;
  const primaryFit = fitText(ctx, slot.starterLabel, primaryBuildFont, 32, 20, maxPillWidth - primaryPadX * 2);
  const primaryBlockWidth = primaryFit.width + primaryPadX * 2;

  // Starter pill — the brand accent, filled, dark text (same recipe as the
  // app's own amber CTA buttons: a saturated accent fill always pairs with
  // dark-navy text here, never white-on-accent).
  ctx.fillStyle = accent;
  roundRectPath(ctx, cx - primaryBlockWidth / 2, cy - primaryHeight / 2, primaryBlockWidth, primaryHeight, primaryHeight / 2);
  ctx.fill();

  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.font = primaryFit.font;
  ctx.fillStyle = ON_ACCENT_DARK;
  ctx.fillText(primaryFit.text, cx, cy + 1);

  if (slot.subLabels.length === 0) return;

  const subLineHeight = 28;
  const subBuildFont = (px: number) => `italic 500 ${px}px ${BODY_FONT}`;
  const maxSubWidth = maxPillWidth + 20;
  const subFits = slot.subLabels.map((label) => fitText(ctx, label, subBuildFont, 22, 15, maxSubWidth - 32));
  const subBlockWidth = Math.max(...subFits.map((f) => f.width)) + 32;
  const subBlockHeight = slot.subLabels.length * subLineHeight + 16;
  const subTop = cy + primaryHeight / 2 + 8;

  ctx.fillStyle = 'rgba(10, 14, 24, 0.55)';
  roundRectPath(ctx, cx - subBlockWidth / 2, subTop, subBlockWidth, subBlockHeight, 12);
  ctx.fill();

  ctx.fillStyle = 'rgba(255, 255, 255, 0.82)';
  subFits.forEach(({ font, text }, i) => {
    ctx.font = font;
    ctx.fillText(text, cx, subTop + 16 + i * subLineHeight);
  });
}

function drawHeader(
  ctx: CanvasRenderingContext2D,
  width: number,
  crest: HTMLImageElement | null,
  opponent: string,
  subtitle: string
): void {
  const centerX = width / 2;
  let y = 40;

  if (crest) {
    const crestSize = 92;
    ctx.drawImage(crest, centerX - crestSize / 2, y, crestSize, crestSize);
    y += crestSize + 18;
  } else {
    y += 18;
  }

  ctx.textAlign = 'center';
  ctx.textBaseline = 'alphabetic';
  ctx.font = `800 26px ${DISPLAY_FONT}`;
  ctx.fillStyle = AMBER;
  ctx.fillText('INTER MITENTE', centerX, y + 20);

  ctx.font = `800 36px ${DISPLAY_FONT}`;
  ctx.fillStyle = '#ffffff';
  ctx.fillText(`vs ${opponent}`, centerX, y + 64);

  ctx.font = `500 22px ${BODY_FONT}`;
  ctx.fillStyle = 'rgba(255, 255, 255, 0.7)';
  ctx.fillText(subtitle, centerX, y + 98);
}

function drawLegend(ctx: CanvasRenderingContext2D, width: number, height: number): void {
  const entries: [FormationColorGroup, string][] = [
    ['portero', 'Portero'],
    ['defensa', 'Defensa'],
    ['medio', 'Medio'],
    ['delantero', 'Delantero'],
  ];
  const y = height - LEGEND_HEIGHT / 2;
  const totalWidth = width * 0.78;
  const step = totalWidth / entries.length;
  const startX = (width - totalWidth) / 2 + step / 2;

  ctx.textAlign = 'left';
  ctx.textBaseline = 'middle';
  ctx.font = `600 22px ${BODY_FONT}`;

  entries.forEach(([group, label], i) => {
    const x = startX + i * step - step / 2 + 24;
    ctx.fillStyle = COLOR_GROUP_HEX[group];
    ctx.beginPath();
    ctx.arc(x, y, 9, 0, Math.PI * 2);
    ctx.fill();
    ctx.fillStyle = 'rgba(255, 255, 255, 0.85)';
    ctx.fillText(label, x + 18, y);
  });
}

function playerLabel(player: { firstName: string; lastName: string; jerseyNumber: number | null }): string {
  const name = `${player.firstName} ${player.lastName}`;
  return player.jerseyNumber !== null ? `${name} #${player.jerseyNumber}` : name;
}

function toBlob(canvas: HTMLCanvasElement): Promise<Blob> {
  return new Promise((resolve, reject) => {
    canvas.toBlob((blob) => (blob ? resolve(blob) : reject(new Error('No se pudo generar la imagen'))), 'image/png');
  });
}

/** Renders the callup share card for a saved formation: the app's own
 * navy/amber/violet "floodlight" background, a schematic pitch panel (not a
 * grass photo), one pill token per slot (starter name+number, substitutes
 * smaller/italic below), the club crest, and the position color legend. */
export async function renderFormationImage(
  match: MatchWithSquad,
  preset: FormationPreset,
  formation: MatchFormation
): Promise<{ dataUrl: string; toBlob: () => Promise<Blob> }> {
  const height = computeCanvasHeight(formation);
  const canvas = document.createElement('canvas');
  canvas.width = WIDTH;
  canvas.height = height;
  const ctx = canvas.getContext('2d');
  if (!ctx) throw new Error('Canvas 2D no soportado');

  const [, crest] = await Promise.all([ensureFontsLoaded(), loadImage('/branding/crest.png')]);

  drawCardBackground(ctx, WIDTH, height);
  drawPitchPanel(ctx, WIDTH, height);

  const slotsByKey = new Map(formation.slots.map((s) => [s.slotKey, s]));
  for (const slotDef of preset.slots) {
    const slot = slotsByKey.get(slotDef.key);
    if (!slot) continue;
    drawSlot(ctx, WIDTH, height, {
      x: slotDef.x,
      y: slotDef.y,
      colorGroup: slotDef.colorGroup,
      starterLabel: playerLabel(slot.player),
      subLabels: capSubNames(slot.substitutes.map((s) => playerLabel(s.player))),
    });
  }

  const dateLabel = new Intl.DateTimeFormat('es-ES', { day: 'numeric', month: 'long' }).format(
    new Date(match.matchDate)
  );
  drawHeader(ctx, WIDTH, crest, match.opponent, dateLabel + (match.competition ? ` · ${match.competition}` : ''));
  drawLegend(ctx, WIDTH, height);

  return { dataUrl: canvas.toDataURL('image/png'), toBlob: () => toBlob(canvas) };
}
